_file_map = {
    "assess_clinical_logic.baml": "// Clinical Logic Assessment Function with Tests\n\n// Function to assess clinical logic and medical relationships\nfunction AssessClinicalLogic(data_sample: DataSample) -> LLMValidationResult {\n  client ParallelValidator\n  prompt #\"\n    You are a clinical validation expert with deep knowledge of medical coding, procedures, and clinical workflows.\n\n    Analyze the following healthcare data for clinical logic and medical relationship validity:\n\n    Resource Type: {{ data_sample.resource_type }}\n    Data: {{ data_sample.raw_data }}\n    {% if data_sample.context %}\n    Context:\n    - Source System: {{ data_sample.context.source_system }}\n    - Provider Type: {{ data_sample.context.provider_type }}\n    - Claim Type: {{ data_sample.context.claim_type }}\n    {% endif %}\n\n    Evaluate clinical logic across these dimensions:\n\n    1. **Diagnosis-Procedure Relationships**:\n       - ICD-10-AM diagnoses support the procedures performed\n       - Procedures are clinically appropriate for the conditions\n       - Sequence and timing of procedures make medical sense\n\n    2. **Medical Coding Consistency**:\n       - Primary and secondary diagnoses are compatible\n       - Procedure codes align with diagnostic codes\n       - Modifier codes are used appropriately\n\n    3. **Clinical Workflows**:\n       - Referral patterns are medically justified\n       - Care team composition is appropriate\n       - Service locations match procedure requirements\n\n    4. **Temporal Logic**:\n       - Service dates are chronologically consistent\n       - Pre-authorization dates precede service dates\n       - Follow-up timing is medically appropriate\n\n    5. **Resource Utilization**:\n       - Quantity and frequency of services are reasonable\n       - Medication dosages and frequencies are appropriate\n       - Lab values and ranges are clinically sensible\n\n    6. **Care Coordination**:\n       - Multi-provider coordination is evident\n       - Specialty referrals are justified\n       - Emergency vs. planned care designations are correct\n\n    7. **Medical Necessity**:\n       - Services provided are medically necessary\n       - Appropriate level of care (inpatient vs. outpatient)\n       - Resource intensity matches condition severity\n\n    Identify clinical inconsistencies, impossible medical scenarios, and areas where clinical judgment appears compromised.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test cases for AssessClinicalLogic function\ntest clinical_logic_diabetes_management {\n  functions [AssessClinicalLogic]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-DM-001\",\n              \"patient_id\": \"PAT-DM-123\",\n              \"provider_id\": \"ENDO-PROV-456\",\n              \"diagnosis_code\": \"E11.9\",\n              \"procedure_code\": \"99213\",\n              \"service_date\": \"2024-12-01\",\n              \"follow_up_codes\": [\"83036\", \"82947\"],\n              \"medication_codes\": [\"860975\"],\n              \"previous_visit\": \"2024-09-01\",\n              \"hba1c_result\": \"7.2%\",\n              \"care_team\": [\"endocrinologist\", \"diabetes_educator\", \"nutritionist\"]\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"eClaimLink\"\n        provider_type \"Specialty_Clinic\"\n        claim_type \"Chronic_Disease_Management\"\n      }\n    }\n  }\n}\n\ntest clinical_logic_inconsistent_procedure {\n  functions [AssessClinicalLogic]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-INCONSISTENT-001\",\n              \"patient_id\": \"PAT-ERR-789\",\n              \"provider_id\": \"CARDIO-PROV-123\",\n              \"diagnosis_code\": \"M79.3\",\n              \"procedure_code\": \"33533\",\n              \"service_date\": \"2024-12-01\",\n              \"service_location\": \"outpatient_clinic\",\n              \"anesthesia_type\": \"general\",\n              \"procedure_duration\": \"240_minutes\",\n              \"pre_auth_date\": \"2024-11-30\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"CSV\"\n        provider_type \"Cardiology_Clinic\"\n        claim_type \"Surgical_Procedure\"\n      }\n    }\n  }\n}\n\ntest clinical_logic_emergency_care_pathway {\n  functions [AssessClinicalLogic]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-EMERG-001\",\n              \"patient_id\": \"PAT-EMERG-456\",\n              \"provider_id\": \"ER-PROV-789\",\n              \"diagnosis_code\": \"I46.9\",\n              \"procedure_codes\": [\"92950\", \"93005\", \"36415\"],\n              \"service_date\": \"2024-12-01\",\n              \"service_time\": \"02:30\",\n              \"emergency_designation\": true,\n              \"care_team\": [\"emergency_physician\", \"cardiologist\", \"nurse\"],\n              \"disposition\": \"admitted_to_icu\",\n              \"lab_results\": [\"troponin_elevated\", \"bnp_normal\"],\n              \"imaging\": [\"chest_xray\", \"ecg_abnormal\"]\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"Hospital_System\"\n        provider_type \"Emergency_Department\"\n        claim_type \"Emergency_Care\"\n      }\n    }\n  }\n}\n",
    "clients.baml": "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\n\nclient<llm> CustomGPT4o {\n  provider openai\n  options {\n    model \"gpt-4o\"\n    api_key env.OPENAI_API_KEY\n  }\n}\n\nclient<llm> CustomGPT4oMini {\n  provider openai\n  retry_policy Exponential\n  options {\n    model \"gpt-4o-mini\"\n    api_key env.OPENAI_API_KEY\n  }\n}\n\nclient<llm> CustomSonnet {\n  provider anthropic\n  options {\n    model \"claude-3-5-sonnet-20241022\"\n    api_key env.ANTHROPIC_API_KEY\n  }\n}\n\n\nclient<llm> CustomHaiku {\n  provider anthropic\n  retry_policy Constant\n  options {\n    model \"claude-3-haiku-20240307\"\n    api_key env.ANTHROPIC_API_KEY\n  }\n}\n\n// https://docs.boundaryml.com/docs/snippets/clients/round-robin\nclient<llm> CustomFast {\n  provider round-robin\n  options {\n    // This will alternate between the two clients\n    strategy [CustomGPT4oMini, CustomHaiku]\n  }\n}\n\n// https://docs.boundaryml.com/docs/snippets/clients/fallback\nclient<llm> OpenaiFallback {\n  provider fallback\n  options {\n    // This will try the clients in order until one succeeds\n    strategy [CustomGPT4oMini, CustomGPT4oMini]\n  }\n}\n\n// Gemini 2.5 Flash client for fast parallel healthcare validation\nclient<llm> GeminiFlash {\n  provider google-ai\n  retry_policy HealthcareRetry\n  options {\n    model \"gemini-2.0-flash-exp\"\n    api_key env.GOOGLE_AI_API_KEY\n    generationConfig {\n      temperature 0.1\n      maxOutputTokens 4096\n    }\n    finish_reason_allow_list [\"stop\"]\n  }\n}\n\n// Fast parallel validation client with fallback\nclient<llm> ParallelValidator {\n  provider fallback\n  options {\n    strategy [GeminiFlash, CustomGPT4oMini, CustomHaiku]\n  }\n}\n\n// https://docs.boundaryml.com/docs/snippets/clients/retry\nretry_policy Constant {\n  max_retries 3\n  // Strategy is optional\n  strategy {\n    type constant_delay\n    delay_ms 200\n  }\n}\n\nretry_policy Exponential {\n  max_retries 2\n  // Strategy is optional\n  strategy {\n    type exponential_backoff\n    delay_ms 300\n    multiplier 1.5\n    max_delay_ms 10000\n  }\n}\n\nretry_policy HealthcareRetry {\n  max_retries 3\n  strategy {\n    type exponential_backoff\n    delay_ms 500\n    multiplier 2.0\n    max_delay_ms 15000\n  }\n}\n",
    "comprehensive_validation.baml": "// Comprehensive Validation Function with Tests\n\n// Function to perform comprehensive parallel validation\nfunction ComprehensiveValidation(data_sample: DataSample) -> UIFriendlyReport {\n  client ParallelValidator\n  prompt #\"\n    You are a comprehensive healthcare data validation system for UAE insurance platforms.\n\n    Perform a complete validation analysis of the following healthcare data:\n\n    Resource Type: {{ data_sample.resource_type }}\n    Data: {{ data_sample.raw_data }}\n    {% if data_sample.context %}\n    Context:\n    - Source: {{ data_sample.context.source_system }}\n    - Emirate: {{ data_sample.context.emirate }}\n    - Provider: {{ data_sample.context.provider_type }}\n    - Patient: {{ data_sample.context.patient_category }}\n    {% endif %}\n\n    Perform validation across ALL these areas simultaneously:\n\n    **1. UAE Compliance Validation**\n    - DHA/DOH regulatory requirements\n    - Authorization and licensing\n    - Patient category compliance\n    - PDPL data privacy compliance\n\n    **2. Clinical Logic Assessment**\n    - Diagnosis-procedure relationships\n    - Medical coding consistency\n    - Clinical workflow appropriateness\n    - Care coordination logic\n\n    **3. Data Quality Analysis**\n    - Completeness and format validation\n    - Pattern anomaly detection\n    - Reference integrity checks\n    - Value range validation\n\n    **4. Medical Code Verification**\n    - ICD-10-AM, CPT, SNOMED validation\n    - UAE local coding compliance\n    - Code relationship verification\n    - Version currency checks\n\n    Synthesize findings into a comprehensive, actionable report that:\n    - Provides an overall quality assessment\n    - Prioritizes issues by severity and impact\n    - Groups related problems together\n    - Offers specific, actionable recommendations\n    - Considers the UAE healthcare context\n\n    Create a user-friendly summary suitable for:\n    - Healthcare administrators\n    - Clinical staff\n    - Compliance officers\n    - Insurance processors\n\n    Focus on practical next steps and clear explanations of why issues matter for patient care and regulatory compliance.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test cases for ComprehensiveValidation function\ntest comprehensive_validation_excellent_quality {\n  functions [ComprehensiveValidation]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"DHA-CLM-2024-PERFECT\",\n              \"patient_id\": \"UAE-NAT-123456\",\n              \"provider_id\": \"DHA-PROV-PREMIUM-789\",\n              \"authorization_id\": \"DHA-AUTH-2024-001\",\n              \"diagnosis_codes\": [\"E11.9\", \"I10\"],\n              \"procedure_codes\": [\"99213\", \"83036\"],\n              \"amount\": 275.50,\n              \"currency\": \"AED\",\n              \"service_date\": \"2024-12-01\",\n              \"pre_auth_date\": \"2024-11-28\",\n              \"emirate\": \"Dubai\",\n              \"patient_category\": \"UAE_National\",\n              \"provider_license\": \"DHA-LIC-2024-VALID\",\n              \"facility_accreditation\": \"DHA-FAC-ACC-2024\",\n              \"care_team\": [\"endocrinologist\", \"nurse\"],\n              \"emergency_designation\": false,\n              \"follow_up_scheduled\": true,\n              \"medication_reconciliation\": \"completed\",\n              \"consent_documented\": true,\n              \"pdpl_compliant\": true\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"eClaimLink\"\n        emirate \"Dubai\"\n        provider_type \"Specialty_Clinic\"\n        patient_category \"UAE_National\"\n        processing_date \"2024-12-01T10:00:00Z\"\n        claim_type \"Chronic_Disease_Management\"\n      }\n    }\n  }\n}\n\ntest comprehensive_validation_multiple_issues {\n  functions [ComprehensiveValidation]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-ISSUES-001\",\n              \"patient_id\": \"PAT-PROB-456\",\n              \"provider_id\": \"UNLICENSED-PROV-123\",\n              \"diagnosis_codes\": [\"250.00\", \"XXX.XX\"],\n              \"procedure_codes\": [\"33533\", \"INVALID\"],\n              \"amount\": 15000.00,\n              \"currency\": \"USD\",\n              \"service_date\": \"2025-06-15\",\n              \"authorization_date\": \"2024-12-01\",\n              \"emirate\": \"Unknown\",\n              \"patient_category\": \"Visitor\",\n              \"service_location\": \"outpatient_clinic\",\n              \"anesthesia_type\": \"general\",\n              \"emergency_designation\": false,\n              \"consent_documented\": false,\n              \"cross_emirates_referral\": true,\n              \"referring_emirate\": \"Sharjah\",\n              \"coding_version\": \"ICD-9-CM-2015\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"CSV\"\n        emirate \"Dubai\"\n        provider_type \"Cardiology_Clinic\"\n        patient_category \"Visitor\"\n        processing_date \"2024-12-01T14:30:00Z\"\n        claim_type \"High_Value_Procedure\"\n      }\n    }\n  }\n}\n\ntest comprehensive_validation_emergency_scenario {\n  functions [ComprehensiveValidation]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-EMERG-CRITICAL\",\n              \"patient_id\": \"PAT-EMERG-789\",\n              \"provider_id\": \"ER-PROV-456\",\n              \"diagnosis_codes\": [\"I46.9\", \"R57.0\"],\n              \"procedure_codes\": [\"92950\", \"93005\", \"36415\"],\n              \"amount\": 12500.00,\n              \"currency\": \"AED\",\n              \"service_date\": \"2024-12-01\",\n              \"service_time\": \"02:30\",\n              \"emirate\": \"Abu Dhabi\",\n              \"patient_category\": \"UAE_Resident\",\n              \"emergency_designation\": true,\n              \"authorization_required\": false,\n              \"care_team\": [\"emergency_physician\", \"cardiologist\", \"nurse\", \"pharmacist\"],\n              \"disposition\": \"admitted_to_icu\",\n              \"lab_results\": [\"troponin_elevated\", \"lactate_high\"],\n              \"imaging\": [\"chest_xray_abnormal\", \"ecg_vfib\"],\n              \"medications_administered\": [\"epinephrine\", \"amiodarone\"],\n              \"consent_waived\": \"emergency_life_threatening\",\n              \"next_of_kin_contacted\": true,\n              \"quality_indicators\": {\n                \"door_to_balloon_time\": \"45_minutes\",\n                \"response_time\": \"3_minutes\",\n                \"documentation_complete\": true\n              }\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"Hospital_System\"\n        emirate \"Abu Dhabi\"\n        provider_type \"Emergency_Department\"\n        patient_category \"UAE_Resident\"\n        processing_date \"2024-12-01T08:00:00Z\"\n        claim_type \"Emergency_Life_Threatening\"\n      }\n    }\n  }\n}\n",
    "detect_data_anomalies.baml": "// Data Anomaly Detection Function with Tests\n\n// Function to detect data anomalies and quality issues\nfunction DetectDataAnomalies(data_sample: DataSample) -> LLMValidationResult {\n  client ParallelValidator\n  prompt #\"\n    You are a healthcare data quality analyst specializing in pattern recognition and anomaly detection.\n\n    Analyze the following healthcare data for anomalies, inconsistencies, and quality issues:\n\n    Resource Type: {{ data_sample.resource_type }}\n    Data: {{ data_sample.raw_data }}\n    {% if data_sample.context %}\n    Context:\n    - Source System: {{ data_sample.context.source_system }}\n    - Processing Date: {{ data_sample.context.processing_date }}\n    {% endif %}\n\n    Detect anomalies across these categories:\n\n    1. **Data Completeness**:\n       - Required fields that are missing or empty\n       - Optional fields that should be present given the context\n       - Incomplete FHIR resource structures\n\n    2. **Format and Structure Issues**:\n       - Invalid date formats or impossible dates\n       - Malformed identifiers or reference patterns\n       - Incorrect data types for fields\n\n    3. **Value Range Anomalies**:\n       - Numerical values outside expected ranges\n       - Unusual quantities or amounts\n       - Suspicious patterns in monetary values\n\n    4. **Reference Integrity**:\n       - Broken references between resources\n       - Circular reference patterns\n       - Missing referenced resources\n\n    5. **Pattern Anomalies**:\n       - Unusual frequency patterns in service delivery\n       - Anomalous provider behavior patterns\n       - Statistical outliers in resource utilization\n\n    6. **Consistency Issues**:\n       - Conflicting information within the same record\n       - Inconsistent formatting across similar fields\n       - Version conflicts between related data elements\n\n    7. **Duplicate Detection**:\n       - Potential duplicate records or claims\n       - Similar patients with different identifiers\n       - Repeated procedures with identical details\n\n    8. **Temporal Anomalies**:\n       - Future dates in historical records\n       - Impossible time sequences\n       - Services provided outside business hours without emergency designation\n\n    Flag unusual patterns, statistical outliers, and data that doesn't conform to expected healthcare data distributions.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test cases for DetectDataAnomalies function\ntest anomaly_detection_outlier_amounts {\n  functions [DetectDataAnomalies]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-OUTLIER-001\",\n              \"patient_id\": \"PAT-123\",\n              \"provider_id\": \"PROV-456\",\n              \"diagnosis_code\": \"Z00.00\",\n              \"procedure_code\": \"99213\",\n              \"amount\": 50000.00,\n              \"currency\": \"AED\",\n              \"service_date\": \"2024-12-01\",\n              \"quantity\": 1,\n              \"typical_range\": \"150-300 AED\"\n            },\n            {\n              \"claim_id\": \"CLM-NORMAL-002\",\n              \"patient_id\": \"PAT-789\",\n              \"provider_id\": \"PROV-456\",\n              \"diagnosis_code\": \"Z00.00\",\n              \"procedure_code\": \"99213\",\n              \"amount\": 180.00,\n              \"currency\": \"AED\",\n              \"service_date\": \"2024-12-01\",\n              \"quantity\": 1\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"CSV\"\n        processing_date \"2024-12-01T10:00:00Z\"\n      }\n    }\n  }\n}\n\ntest anomaly_detection_temporal_issues {\n  functions [DetectDataAnomalies]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-TIME-001\",\n              \"patient_id\": \"PAT-TIME-123\",\n              \"provider_id\": \"PROV-789\",\n              \"diagnosis_code\": \"E11.9\",\n              \"procedure_code\": \"99213\",\n              \"amount\": 150.00,\n              \"currency\": \"AED\",\n              \"service_date\": \"2025-06-15\",\n              \"authorization_date\": \"2024-12-01\",\n              \"birth_date\": \"1990-05-20\",\n              \"processing_date\": \"2024-12-01\"\n            },\n            {\n              \"claim_id\": \"CLM-SEQ-002\",\n              \"patient_id\": \"PAT-TIME-123\",\n              \"provider_id\": \"PROV-789\",\n              \"diagnosis_code\": \"E11.9\",\n              \"procedure_code\": \"83036\",\n              \"service_date\": \"2024-11-30\",\n              \"result_date\": \"2024-11-25\",\n              \"follow_up_scheduled\": \"2024-11-20\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"eClaimLink\"\n        processing_date \"2024-12-01T14:00:00Z\"\n      }\n    }\n  }\n}\n\ntest anomaly_detection_duplicate_patterns {\n  functions [DetectDataAnomalies]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-DUP-001\",\n              \"patient_id\": \"PAT-DUP-123\",\n              \"provider_id\": \"PROV-456\",\n              \"diagnosis_code\": \"M79.3\",\n              \"procedure_code\": \"99213\",\n              \"amount\": 150.00,\n              \"service_date\": \"2024-12-01\",\n              \"service_time\": \"10:00\"\n            },\n            {\n              \"claim_id\": \"CLM-DUP-002\",\n              \"patient_id\": \"PAT-DUP-456\",\n              \"provider_id\": \"PROV-456\",\n              \"diagnosis_code\": \"M79.3\",\n              \"procedure_code\": \"99213\",\n              \"amount\": 150.00,\n              \"service_date\": \"2024-12-01\",\n              \"service_time\": \"10:00\",\n              \"patient_name\": \"Ahmed Al-Mansouri\",\n              \"similar_demographics\": true\n            },\n            {\n              \"claim_id\": \"CLM-DUP-003\",\n              \"patient_id\": \"PAT-DUP-123\",\n              \"provider_id\": \"PROV-456\",\n              \"diagnosis_code\": \"M79.3\",\n              \"procedure_code\": \"99213\",\n              \"amount\": 150.00,\n              \"service_date\": \"2024-12-01\",\n              \"service_time\": \"10:05\",\n              \"submission_time\": \"2024-12-01T15:30:00Z\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"CSV\"\n        processing_date \"2024-12-01T16:00:00Z\"\n      }\n    }\n  }\n}\n",
    "generate_quality_metrics.baml": "// Quality Metrics Generation Function with Tests\n\n// Function to generate quality metrics and scoring\nfunction GenerateQualityMetrics(validation_results: LLMValidationResult[]) -> QualityScore {\n  client ParallelValidator\n  prompt #\"\n    You are a healthcare data quality analyst tasked with generating comprehensive quality scores.\n\n    Based on the following validation results from multiple LLM validators:\n\n    {% for result in validation_results %}\n    Validation Result {{ loop.index }}:\n    - Validation Passed: {{ result.validation_passed }}\n    - Confidence Score: {{ result.confidence_score }}\n    - Issues Count: {{ result.issues|length }}\n    - Quality Metrics: {{ result.quality_metrics }}\n    {% endfor %}\n\n    Generate a comprehensive quality score that includes:\n\n    1. **Overall Score** (0.0 to 1.0):\n       - Weighted combination of all validation dimensions\n       - Consider issue severity and frequency\n       - Account for validator confidence levels\n\n    2. **Dimensional Scores**:\n       - Compliance Score: UAE regulatory adherence\n       - Clinical Logic Score: Medical appropriateness\n       - Data Completeness Score: Required field presence\n       - Code Validity Score: Medical coding accuracy\n\n    3. **Issue Quantification**:\n       - Total issues across all validators\n       - Breakdown by severity (critical, error, warning, info)\n       - Issue frequency analysis\n\n    4. **Quality Assessment**:\n       - Identify the strongest and weakest areas\n       - Calculate improvement potential\n       - Assess data fitness for processing\n\n    Use these scoring guidelines:\n    - 0.9-1.0: Excellent quality, minimal issues\n    - 0.8-0.89: Good quality, minor issues\n    - 0.7-0.79: Acceptable quality, some issues need attention\n    - 0.6-0.69: Poor quality, significant issues present\n    - 0.0-0.59: Unacceptable quality, major remediation required\n\n    Weight critical and error issues more heavily than warnings and info items.\n    Consider the UAE healthcare context where compliance issues are particularly important.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Simple test for quality metrics\ntest quality_metrics_simple {\n  functions [GenerateQualityMetrics]\n  args {\n    validation_results #\"\n      [\n        {\n          \"validation_passed\": true,\n          \"confidence_score\": 0.95,\n          \"issues\": [],\n          \"quality_metrics\": {\"compliance_score\": 0.98},\n          \"processing_time_ms\": 1200,\n          \"model_used\": \"gemini-2.5-flash\"\n        }\n      ]\n    \"#\n  }\n}\n",
    "generate_recommendations.baml": "// Recommendations Generation Function with Tests\n\n// Function to create actionable recommendations\nfunction GenerateRecommendations(quality_report: DataQualityReport) -> ActionableItem[] {\n  client ParallelValidator\n  prompt #\"\n    You are a healthcare data improvement consultant specializing in UAE healthcare systems.\n\n    Based on the following quality assessment report:\n\n    Quality Score: {{ quality_report.quality_score.overall_score }}\n    Total Issues: {{ quality_report.quality_score.total_issues }}\n    Critical Issues: {{ quality_report.quality_score.critical_issues }}\n\n    Issues Summary:\n    {% for issue in quality_report.validation_issues %}\n    - {{ issue.severity }}: {{ issue.message }} ({{ issue.type }})\n    {% endfor %}\n\n    Generate specific, actionable recommendations for improving data quality:\n\n    **Prioritization Criteria**:\n    1. Patient safety impact\n    2. Regulatory compliance risk\n    3. Financial impact\n    4. Implementation effort required\n\n    **Recommendation Categories**:\n    1. **Immediate Actions** (High Priority):\n       - Critical compliance violations\n       - Patient safety concerns\n       - Data corruption issues\n\n    2. **Short-term Improvements** (Medium Priority):\n       - Process standardization\n       - Training requirements\n       - System configuration updates\n\n    3. **Long-term Enhancements** (Lower Priority):\n       - Workflow optimization\n       - Technology upgrades\n       - Advanced quality monitoring\n\n    **For Each Recommendation**:\n    - Provide specific fix instructions\n    - Estimate implementation effort\n    - Identify responsible parties\n    - Include UAE regulatory context\n    - Suggest validation methods\n\n    Focus on practical, achievable improvements that align with UAE healthcare standards and can be implemented by typical healthcare organizations.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Simple test for recommendations\ntest recommendations_simple {\n  functions [GenerateRecommendations]\n  args {\n    quality_report #\"\n      {\n        \"bundle_id\": \"test-bundle-001\",\n        \"assessed_at\": \"2024-12-01T10:00:00Z\",\n        \"quality_score\": {\n          \"overall_score\": 0.88,\n          \"compliance_score\": 0.92,\n          \"clinical_logic_score\": 0.85,\n          \"data_completeness_score\": 0.90,\n          \"code_validity_score\": 0.85,\n          \"total_issues\": 3,\n          \"critical_issues\": 0,\n          \"error_issues\": 0,\n          \"warning_issues\": 2,\n          \"info_issues\": 1\n        },\n        \"validation_issues\": [\n          {\n            \"id\": \"WARN-001\",\n            \"type\": \"CLINICAL\",\n            \"severity\": \"WARNING\",\n            \"code\": \"FOLLOW_UP_MISSING\",\n            \"message\": \"Follow-up appointment not scheduled\"\n          }\n        ],\n        \"summary\": {\n          \"total_records\": 1,\n          \"valid_records\": 1,\n          \"invalid_records\": 0\n        },\n        \"total_resources\": 5,\n        \"resources_assessed\": 5\n      }\n    \"#\n  }\n}\n",
    "generators.baml": "// This helps use auto generate libraries you can use in the language of\n// your choice. You can have multiple generators if you use multiple languages.\n// Just ensure that the output_dir is different for each generator.\ngenerator target {\n    // Valid values: \"python/pydantic\", \"typescript\", \"ruby/sorbet\", \"rest/openapi\"\n    output_type \"python/pydantic\"\n\n    // Where the generated code will be saved (relative to baml_src/)\n    output_dir \"../\"\n\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\n    // The BAML VSCode extension version should also match this version.\n    version \"0.203.1\"\n\n    // Valid values: \"sync\", \"async\"\n    // This controls what `b.FunctionName()` will be (sync or async).\n    default_client_mode sync\n}\n",
    "healthcare_models.baml": "// Healthcare FHIR-compliant models for UAE insurance validation\n\n// Core money representation for healthcare claims\nclass MoneyAmount {\n  value float\n  currency string @description(\"Currency code (AED, USD, etc.)\")\n}\n\n// Medical coding systems used in UAE healthcare\nenum CodingSystem {\n  ICD_10_AM @description(\"ICD-10-AM used in UAE\")\n  CPT @description(\"Current Procedural Terminology\")\n  SNOMED_CT @description(\"Systematized Nomenclature of Medicine Clinical Terms\")\n  LOINC @description(\"Logical Observation Identifiers Names and Codes\")\n  DHA_LOCAL @description(\"Dubai Health Authority local codes\")\n  DOH_LOCAL @description(\"Abu Dhabi Department of Health local codes\")\n  UNKNOWN\n}\n\n// Medical code with validation support\nclass MedicalCode {\n  code string\n  system CodingSystem\n  display string?\n  version string?\n}\n\n// UAE healthcare providers and payers\nenum UAEHealthcareEntity {\n  DHA @description(\"Dubai Health Authority\")\n  DOH_AD @description(\"Abu Dhabi Department of Health\")\n  MOHAP @description(\"Ministry of Health and Prevention\")\n  SEHA @description(\"SEHA Health System\")\n  DHA_INSURANCE @description(\"DHA Insurance companies\")\n  PRIVATE_INSURANCE @description(\"Private insurance providers\")\n  UNKNOWN\n}\n\n// FHIR Bundle structure for healthcare data\nclass HealthcareBundle {\n  resourceType string @description(\"Always 'Bundle' for FHIR compliance\")\n  id string?\n  meta BundleMeta?\n  identifier BundleIdentifier?\n  type string @description(\"Bundle type: document, message, transaction, etc.\")\n  timestamp string? @description(\"ISO 8601 timestamp\")\n  total int? @description(\"Number of resources in bundle\")\n\n  // Essential UAE healthcare fields\n  authorization_id string?\n  sender UAEHealthcareEntity?\n  receiver UAEHealthcareEntity?\n\n  // FHIR resources\n  entry BundleEntry[]\n\n  // Preserve original data\n  raw_data map<string, string>? @description(\"Original XML/CSV data preserved\")\n  processing_metadata ProcessingMetadata?\n}\n\nclass BundleMeta {\n  lastUpdated string? @description(\"ISO 8601 timestamp\")\n  profile string[]? @description(\"FHIR profiles this bundle conforms to\")\n  source string? @description(\"Source system URI\")\n  tag Coding[]? @description(\"Tags applied to this bundle\")\n}\n\nclass BundleIdentifier {\n  use string? @description(\"usual | official | temp | secondary\")\n  type CodeableConcept?\n  system string? @description(\"Namespace for the identifier\")\n  value string @description(\"The identifier value\")\n  period Period?\n}\n\nclass BundleEntry {\n  id string?\n  resource FHIRResource\n  fullUrl string? @description(\"Absolute URL for the resource\")\n  search EntrySearch?\n  request EntryRequest?\n  response EntryResponse?\n}\n\nclass Period {\n  start string? @description(\"ISO 8601 start date\")\n  end string? @description(\"ISO 8601 end date\")\n}\n\nclass CodeableConcept {\n  coding Coding[]?\n  text string?\n}\n\nclass Coding {\n  system string?\n  version string?\n  code string?\n  display string?\n  userSelected bool?\n}\n\nclass EntrySearch {\n  mode string? @description(\"match | include | outcome\")\n  score float?\n}\n\nclass EntryRequest {\n  method string @description(\"GET | HEAD | POST | PUT | DELETE | PATCH\")\n  url string\n  ifNoneMatch string?\n  ifModifiedSince string?\n  ifMatch string?\n  ifNoneExist string?\n}\n\nclass EntryResponse {\n  status string @description(\"HTTP response status\")\n  location string?\n  etag string?\n  lastModified string?\n  outcome OperationOutcome?\n}\n\nclass OperationOutcome {\n  resourceType string @description(\"Always 'OperationOutcome'\")\n  issue OutcomeIssue[]\n}\n\nclass OutcomeIssue {\n  severity string @description(\"fatal | error | warning | information\")\n  code string\n  details CodeableConcept?\n  diagnostics string?\n  location string[]?\n  expression string[]?\n}\n\n// FHIR Resource union type for different resource types\nclass FHIRResource {\n  resourceType string\n  id string?\n  meta ResourceMeta?\n  implicitRules string?\n  language string?\n\n  // Resource-specific data (varies by resourceType)\n  data map<string, string> @description(\"Resource-specific fields as key-value pairs\")\n}\n\nclass ResourceMeta {\n  versionId string?\n  lastUpdated string?\n  source string?\n  profile string[]?\n  security Coding[]?\n  tag Coding[]?\n}\n\n// Specific FHIR resource types for healthcare\nclass ClaimResource {\n  resourceType string @description(\"Always 'Claim'\")\n  id string?\n  status string @description(\"active | cancelled | draft | entered-in-error\")\n  type CodeableConcept @description(\"Claim type (institutional, professional, etc.)\")\n  use string @description(\"claim | preauthorization | predetermination\")\n\n  patient Reference @description(\"Patient reference\")\n  created string @description(\"ISO 8601 creation date\")\n  insurer Reference @description(\"Target insurer\")\n  provider Reference @description(\"Provider responsible for claim\")\n\n  priority CodeableConcept? @description(\"Processing priority\")\n  fundsReserve CodeableConcept? @description(\"Funds requested to be reserved\")\n\n  // UAE specific fields\n  authorization_id string?\n  emirate string? @description(\"UAE Emirate where service provided\")\n\n  related ClaimRelated[]?\n  payee ClaimPayee?\n  referral Reference?\n  facility Reference?\n  careTeam ClaimCareTeam[]?\n  supportingInfo ClaimSupportingInfo[]?\n  diagnosis ClaimDiagnosis[]?\n  procedure ClaimProcedure[]?\n  insurance ClaimInsurance[]\n  item ClaimItem[]?\n  total MoneyAmount?\n}\n\nclass Reference {\n  reference string?\n  type string?\n  identifier Identifier?\n  display string?\n}\n\nclass Identifier {\n  use string?\n  type CodeableConcept?\n  system string?\n  value string\n  period Period?\n  assigner Reference?\n}\n\nclass ClaimRelated {\n  claim Reference?\n  relationship CodeableConcept?\n  reference Identifier?\n}\n\nclass ClaimPayee {\n  type CodeableConcept\n  party Reference?\n}\n\nclass ClaimCareTeam {\n  sequence int\n  provider Reference\n  responsible bool?\n  role CodeableConcept?\n  qualification CodeableConcept?\n}\n\nclass ClaimSupportingInfo {\n  sequence int\n  category CodeableConcept\n  code CodeableConcept?\n  timing_date string? @description(\"ISO 8601 date\")\n  timing_period Period?\n  value_boolean bool?\n  value_string string?\n  value_quantity Quantity?\n  value_attachment Attachment?\n  value_reference Reference?\n  reason Coding?\n}\n\nclass Quantity {\n  value float?\n  comparator string? @description(\"< | <= | >= | >\")\n  unit string?\n  system string?\n  code string?\n}\n\nclass Attachment {\n  contentType string?\n  language string?\n  data string? @description(\"Base64 encoded data\")\n  url string?\n  size int?\n  hash string?\n  title string?\n  creation string? @description(\"ISO 8601 date\")\n}\n\nclass ClaimDiagnosis {\n  sequence int\n  diagnosis_codeable_concept CodeableConcept?\n  diagnosis_reference Reference?\n  type CodeableConcept[]?\n  on_admission CodeableConcept?\n  package_code CodeableConcept?\n}\n\nclass ClaimProcedure {\n  sequence int\n  type CodeableConcept[]?\n  date string? @description(\"ISO 8601 date\")\n  procedure_codeable_concept CodeableConcept?\n  procedure_reference Reference?\n  udi Reference[]?\n}\n\nclass ClaimInsurance {\n  sequence int\n  focal bool\n  identifier Identifier?\n  coverage Reference\n  business_arrangement string?\n  pre_auth_ref string[]?\n  claim_response Reference?\n}\n\nclass ClaimItem {\n  sequence int\n  care_team_sequence int[]?\n  diagnosis_sequence int[]?\n  procedure_sequence int[]?\n  information_sequence int[]?\n  revenue CodeableConcept?\n  category CodeableConcept?\n  product_or_service CodeableConcept\n  modifier CodeableConcept[]?\n  program_code CodeableConcept[]?\n\n  serviced_date string? @description(\"ISO 8601 date\")\n  serviced_period Period?\n  location_codeable_concept CodeableConcept?\n  location_address Address?\n  location_reference Reference?\n\n  quantity Quantity?\n  unit_price MoneyAmount?\n  factor float?\n  net MoneyAmount?\n  udi Reference[]?\n  body_site CodeableConcept[]?\n  sub_site CodeableConcept[]?\n  encounter Reference[]?\n  detail ClaimItemDetail[]?\n}\n\nclass Address {\n  use string? @description(\"home | work | temp | old | billing\")\n  type string? @description(\"postal | physical | both\")\n  text string?\n  line string[]?\n  city string?\n  district string?\n  state string?\n  postalCode string?\n  country string?\n  period Period?\n}\n\nclass ClaimItemDetail {\n  sequence int\n  revenue CodeableConcept?\n  category CodeableConcept?\n  product_or_service CodeableConcept\n  modifier CodeableConcept[]?\n  program_code CodeableConcept[]?\n  quantity Quantity?\n  unit_price MoneyAmount?\n  factor float?\n  net MoneyAmount?\n  udi Reference[]?\n  sub_detail ClaimItemSubDetail[]?\n}\n\nclass ClaimItemSubDetail {\n  sequence int\n  revenue CodeableConcept?\n  category CodeableConcept?\n  product_or_service CodeableConcept\n  modifier CodeableConcept[]?\n  program_code CodeableConcept[]?\n  quantity Quantity?\n  unit_price MoneyAmount?\n  factor float?\n  net MoneyAmount?\n  udi Reference[]?\n}\n\n// Observation resource for clinical data\nclass ObservationResource {\n  resourceType string @description(\"Always 'Observation'\")\n  id string?\n  status string @description(\"registered | preliminary | final | amended | corrected | cancelled | entered-in-error | unknown\")\n  category CodeableConcept[]?\n  code CodeableConcept @description(\"Type of observation\")\n\n  subject Reference @description(\"Patient reference\")\n  encounter Reference?\n  effective_date_time string? @description(\"ISO 8601 datetime\")\n  effective_period Period?\n\n  issued string? @description(\"ISO 8601 datetime when result was issued\")\n  performer Reference[]?\n\n  value_quantity Quantity?\n  value_codeable_concept CodeableConcept?\n  value_string string?\n  value_boolean bool?\n  value_integer int?\n  value_range Range?\n  value_ratio Ratio?\n  value_sampled_data SampledData?\n  value_time string?\n  value_date_time string?\n  value_period Period?\n\n  data_absent_reason CodeableConcept?\n  interpretation CodeableConcept[]?\n  note Annotation[]?\n  body_site CodeableConcept?\n  method CodeableConcept?\n  specimen Reference?\n  device Reference?\n  reference_range ObservationReferenceRange[]?\n  has_member Reference[]?\n  derived_from Reference[]?\n  component ObservationComponent[]?\n}\n\nclass Range {\n  low Quantity?\n  high Quantity?\n}\n\nclass Ratio {\n  numerator Quantity?\n  denominator Quantity?\n}\n\nclass SampledData {\n  origin Quantity\n  period float\n  factor float?\n  lower_limit float?\n  upper_limit float?\n  dimensions int\n  data string?\n}\n\nclass Annotation {\n  author_reference Reference?\n  author_string string?\n  time string? @description(\"ISO 8601 datetime\")\n  text string\n}\n\nclass ObservationReferenceRange {\n  low Quantity?\n  high Quantity?\n  type CodeableConcept?\n  applies_to CodeableConcept[]?\n  age Range?\n  text string?\n}\n\nclass ObservationComponent {\n  code CodeableConcept\n  value_quantity Quantity?\n  value_codeable_concept CodeableConcept?\n  value_string string?\n  value_boolean bool?\n  value_integer int?\n  value_range Range?\n  value_ratio Ratio?\n  value_sampled_data SampledData?\n  value_time string?\n  value_date_time string?\n  value_period Period?\n\n  data_absent_reason CodeableConcept?\n  interpretation CodeableConcept[]?\n  reference_range ObservationReferenceRange[]?\n}\n\n// Service activity for procedure tracking\nclass ServiceActivity {\n  id string\n  type string @description(\"procedure | medication | observation | diagnostic\")\n  code MedicalCode\n  description string?\n  status string @description(\"planned | in-progress | completed | cancelled\")\n\n  patient_reference string\n  performer_reference string?\n  encounter_reference string?\n\n  performed_date string? @description(\"ISO 8601 date\")\n  performed_period Period?\n\n  location string?\n  outcome CodeableConcept?\n  notes string?\n\n  // UAE specific\n  emirate string?\n  facility_license string?\n  provider_license string?\n}\n\n// Processing metadata\nclass ProcessingMetadata {\n  processed_at string @description(\"ISO 8601 timestamp\")\n  processor_version string?\n  source_format string @description(\"xml | csv | json\")\n  source_system string? @description(\"eClaimLink | Shafafiya | CSV\")\n\n  warnings ProcessingWarning[]?\n  errors ProcessingError[]?\n\n  // Data quality metrics\n  completeness_score float? @description(\"0.0 to 1.0\")\n  validity_score float? @description(\"0.0 to 1.0\")\n  consistency_score float? @description(\"0.0 to 1.0\")\n\n  total_records int?\n  processed_records int?\n  failed_records int?\n}\n\nclass ProcessingWarning {\n  code string\n  message string\n  field string?\n  severity string @description(\"low | medium | high\")\n}\n\nclass ProcessingError {\n  code string\n  message string\n  field string?\n  value string?\n  severity string @description(\"error | critical\")\n}\n\n// Data quality assessment structures\nenum ValidationSeverity {\n  INFO\n  WARNING\n  ERROR\n  CRITICAL\n}\n\nenum ValidationType {\n  COMPLIANCE @description(\"UAE healthcare compliance rules\")\n  CLINICAL @description(\"Medical logic and relationships\")\n  DATA_QUALITY @description(\"Data consistency and completeness\")\n  CODE_VALIDATION @description(\"Medical code verification\")\n}\n\nclass ValidationIssue {\n  id string\n  type ValidationType\n  severity ValidationSeverity\n  code string @description(\"Issue code for categorization\")\n  message string @description(\"Human-readable description\")\n\n  field_path string? @description(\"JSON path to problematic field\")\n  expected_value string?\n  actual_value string?\n\n  resource_type string? @description(\"FHIR resource type affected\")\n  resource_id string?\n\n  suggestions string[]? @description(\"Recommended fixes\")\n\n  // UAE specific context\n  regulation_reference string? @description(\"UAE regulation reference\")\n  emirate_specific bool? @description(\"Emirate-specific rule\")\n}\n\nclass QualityScore {\n  overall_score float @description(\"0.0 to 1.0\")\n\n  compliance_score float @description(\"UAE healthcare compliance\")\n  clinical_logic_score float @description(\"Medical relationships validity\")\n  data_completeness_score float @description(\"Required fields present\")\n  code_validity_score float @description(\"Medical codes are valid\")\n\n  total_issues int\n  critical_issues int\n  error_issues int\n  warning_issues int\n  info_issues int\n}\n\nclass DataQualityReport {\n  bundle_id string?\n  assessed_at string @description(\"ISO 8601 timestamp\")\n\n  quality_score QualityScore\n  validation_issues ValidationIssue[]\n\n  summary DataQualitySummary\n  recommendations string[]?\n\n  // Processing context\n  total_resources int\n  resources_assessed int\n  assessment_duration_ms int?\n}\n\nclass DataQualitySummary {\n  total_records int\n  valid_records int\n  invalid_records int\n\n  // Field-level analysis\n  required_fields_missing int\n  invalid_formats int\n  inconsistent_references int\n\n  // UAE healthcare specific\n  missing_authorization_ids int\n  invalid_emirates int\n  unlicensed_providers int\n\n  // Medical coding issues\n  invalid_icd_codes int\n  invalid_cpt_codes int\n  deprecated_codes int\n}\n\n// LLM input structure\nclass DataSample {\n  resource_type string @description(\"Type of healthcare resource\")\n  raw_data string @description(\"Raw data to validate (JSON, XML, or CSV excerpt)\")\n  context DataContext? @description(\"Additional context for validation\")\n}\n\nclass DataContext {\n  source_system string? @description(\"eClaimLink | Shafafiya | CSV\")\n  emirate string? @description(\"UAE Emirate context\")\n  provider_type string? @description(\"hospital | clinic | pharmacy | lab\")\n  patient_category string? @description(\"national | resident | visitor\")\n\n  // Additional context for validation\n  processing_date string? @description(\"ISO 8601 date\")\n  claim_type string? @description(\"institutional | professional | pharmacy | vision | dental\")\n}\n\n// LLM validation output structures\nclass LLMValidationResult {\n  validation_passed bool\n  confidence_score float @description(\"0.0 to 1.0\")\n\n  issues ValidationIssue[]\n  quality_metrics map<string, float> @description(\"Specific quality metrics\")\n\n  processing_time_ms int?\n  model_used string?\n}\n\nclass UIFriendlyReport {\n  status string @description(\"pass | warning | fail\")\n  summary string @description(\"Brief human-readable summary\")\n\n  score QualityScore\n  issues_by_severity map<string, ValidationIssue[]> @description(\"Issues grouped by severity\")\n\n  actionable_items ActionableItem[]\n  next_steps string[]?\n}\n\nclass ActionableItem {\n  priority string @description(\"high | medium | low\")\n  category string @description(\"compliance | clinical | data_quality | coding\")\n  title string\n  description string\n  fix_suggestion string?\n  estimated_effort string? @description(\"quick | moderate | extensive\")\n\n  affected_fields string[]?\n  regulation_reference string?\n}\n",
    "validate_compliance.baml": "// UAE Healthcare Compliance Validation Function with Tests\n\n// Function to validate compliance with UAE healthcare regulations\nfunction ValidateCompliance(data_sample: DataSample) -> LLMValidationResult {\n  client ParallelValidator\n  prompt #\"\n    You are a UAE healthcare compliance expert specializing in Dubai Health Authority (DHA) and Abu Dhabi Department of Health (DOH) regulations.\n\n    Analyze the following healthcare data for compliance with UAE regulations:\n\n    Resource Type: {{ data_sample.resource_type }}\n    Data: {{ data_sample.raw_data }}\n    {% if data_sample.context %}\n    Context:\n    - Source System: {{ data_sample.context.source_system }}\n    - Emirate: {{ data_sample.context.emirate }}\n    - Provider Type: {{ data_sample.context.provider_type }}\n    - Patient Category: {{ data_sample.context.patient_category }}\n    {% endif %}\n\n    Check for compliance with UAE healthcare regulations including:\n\n    1. **Authorization Requirements**:\n       - Valid authorization IDs for pre-authorization claims\n       - Proper DHA/DOH approval workflows\n       - Required documentation for high-value procedures\n\n    2. **Provider Licensing**:\n       - Valid provider licenses for the specified emirate\n       - Scope of practice compliance\n       - Facility accreditation requirements\n\n    3. **Patient Categories**:\n       - Proper patient classification (UAE National, Resident, Visitor)\n       - Insurance eligibility verification\n       - Emergency vs. planned care protocols\n\n    4. **Emirate-Specific Rules**:\n       - Dubai (DHA) specific requirements\n       - Abu Dhabi (DOH) specific requirements\n       - Cross-emirate referral protocols\n\n    5. **Data Privacy (PDPL)**:\n       - Patient data handling compliance\n       - Consent requirements\n       - Data minimization principles\n\n    6. **Billing and Claims**:\n       - Proper coding requirements (ICD-10-AM, CPT)\n       - Price transparency regulations\n       - Fraud prevention measures\n\n    Return your analysis in the specified format, identifying:\n    - Compliance violations with specific regulation references\n    - Missing required fields or documentation\n    - Severity levels for each issue\n    - Actionable recommendations for compliance\n\n    Focus on practical, actionable findings that can be addressed by healthcare providers.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test cases for ValidateCompliance function\ntest compliance_dubai_complete_claim {\n  functions [ValidateCompliance]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"DHA-CLM-2024-001\",\n              \"patient_id\": \"UAE-PAT-123456\",\n              \"provider_id\": \"DHA-PROV-789\",\n              \"authorization_id\": \"DHA-AUTH-2024-001\",\n              \"diagnosis_code\": \"E11.9\",\n              \"procedure_code\": \"99213\",\n              \"amount\": 150.50,\n              \"currency\": \"AED\",\n              \"service_date\": \"2024-12-01\",\n              \"emirate\": \"Dubai\",\n              \"patient_category\": \"UAE_National\",\n              \"provider_license\": \"DHA-LIC-2024-VALID\",\n              \"facility_accreditation\": \"DHA-FAC-ACC-2024\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"eClaimLink\"\n        emirate \"Dubai\"\n        provider_type \"Private_Clinic\"\n        patient_category \"UAE_National\"\n        processing_date \"2024-12-01T10:00:00Z\"\n        claim_type \"Medical\"\n      }\n    }\n  }\n}\n\ntest compliance_missing_authorization {\n  functions [ValidateCompliance]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-NO-AUTH-001\",\n              \"patient_id\": \"PAT-456789\",\n              \"provider_id\": \"PROV-UNLICENSED\",\n              \"diagnosis_code\": \"Z51.11\",\n              \"procedure_code\": \"96413\",\n              \"amount\": 5000.00,\n              \"currency\": \"AED\",\n              \"service_date\": \"2024-12-01\",\n              \"emirate\": \"Dubai\",\n              \"patient_category\": \"Visitor\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"CSV\"\n        emirate \"Dubai\"\n        provider_type \"Hospital\"\n        patient_category \"Visitor\"\n        processing_date \"2024-12-01T14:30:00Z\"\n        claim_type \"High_Value_Procedure\"\n      }\n    }\n  }\n}\n\ntest compliance_cross_emirate_referral {\n  functions [ValidateCompliance]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CROSS-EMI-001\",\n              \"patient_id\": \"UAE-RES-789012\",\n              \"provider_id\": \"DOH-PROV-456\",\n              \"referring_provider_id\": \"DHA-PROV-123\",\n              \"authorization_id\": \"DOH-REF-2024-001\",\n              \"diagnosis_code\": \"C78.00\",\n              \"procedure_code\": \"77301\",\n              \"amount\": 8500.00,\n              \"currency\": \"AED\",\n              \"service_date\": \"2024-12-02\",\n              \"emirate\": \"Abu Dhabi\",\n              \"referring_emirate\": \"Dubai\",\n              \"patient_category\": \"UAE_Resident\",\n              \"emergency_designation\": false\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"Shafafiya\"\n        emirate \"Abu Dhabi\"\n        provider_type \"Specialized_Hospital\"\n        patient_category \"UAE_Resident\"\n        processing_date \"2024-12-02T09:15:00Z\"\n        claim_type \"Specialty_Referral\"\n      }\n    }\n  }\n}\n",
    "validate_medical_codes.baml": "// Medical Code Validation Function with Tests\n\n// Function to validate medical codes against standard coding systems\nfunction ValidateMedicalCodes(data_sample: DataSample) -> LLMValidationResult {\n  client ParallelValidator\n  prompt #\"\n    You are a medical coding specialist with expertise in ICD-10-AM, CPT, SNOMED CT, and UAE-specific coding requirements.\n\n    Validate the medical codes in the following healthcare data:\n\n    Resource Type: {{ data_sample.resource_type }}\n    Data: {{ data_sample.raw_data }}\n    {% if data_sample.context %}\n    Context:\n    - Source System: {{ data_sample.context.source_system }}\n    - Emirate: {{ data_sample.context.emirate }}\n    {% endif %}\n\n    Validate codes across these coding systems:\n\n    1. **ICD-10-AM Validation** (Primary in UAE):\n       - Valid ICD-10-AM code format and structure\n       - Codes exist in current version\n       - Appropriate specificity level\n       - Correct use of combination codes\n       - Valid laterality and encounter type modifiers\n\n    2. **CPT Code Validation**:\n       - Valid CPT code format (5-digit numeric)\n       - Codes are current and not deleted\n       - Appropriate modifiers applied\n       - Bundling rules compliance\n       - Category I, II, III code usage\n\n    3. **SNOMED CT Validation**:\n       - Valid SNOMED CT concept IDs\n       - Appropriate hierarchy relationships\n       - Current terminology version\n       - Correct semantic tags\n\n    4. **LOINC Code Validation**:\n       - Valid LOINC codes for laboratory results\n       - Appropriate units and reference ranges\n       - Correct method and specimen type codes\n\n    5. **UAE Local Codes**:\n       - DHA local coding system compliance\n       - DOH Abu Dhabi specific codes\n       - Emirates-specific procedure codes\n       - Local pharmacy and medication codes\n\n    6. **Code Relationships**:\n       - Primary-secondary diagnosis code relationships\n       - Procedure-diagnosis code compatibility\n       - Cross-reference accuracy between coding systems\n\n    7. **Coding Quality**:\n       - Appropriate code specificity\n       - Complete coding (no unspecified codes when specific codes available)\n       - Proper use of combination vs. separate codes\n       - Correct sequencing of multiple codes\n\n    8. **Version and Currency**:\n       - Codes are from the correct version year\n       - Deprecated codes identification\n       - New code adoptions\n\n    Focus on identifying:\n    - Invalid or non-existent codes\n    - Deprecated or outdated codes\n    - Inappropriate code usage\n    - Missing required modifiers\n    - Coding compliance with UAE standards\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test cases for ValidateMedicalCodes function\ntest medical_codes_valid_standard_codes {\n  functions [ValidateMedicalCodes]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-VALID-001\",\n              \"patient_id\": \"PAT-123\",\n              \"provider_id\": \"PROV-456\",\n              \"diagnosis_codes\": [\"E11.9\", \"I10\", \"Z51.11\"],\n              \"procedure_codes\": [\"99213\", \"83036\", \"85025\"],\n              \"loinc_codes\": [\"4548-4\", \"2345-7\"],\n              \"snomed_codes\": [\"44054006\", \"38341003\"],\n              \"rxnorm_codes\": [\"860975\", \"617314\"],\n              \"service_date\": \"2024-12-01\",\n              \"coding_version\": \"ICD-10-AM-11th-Edition-2024\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"eClaimLink\"\n        emirate \"Dubai\"\n      }\n    }\n  }\n}\n\ntest medical_codes_invalid_deprecated_codes {\n  functions [ValidateMedicalCodes]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-INVALID-001\",\n              \"patient_id\": \"PAT-789\",\n              \"provider_id\": \"PROV-123\",\n              \"diagnosis_codes\": [\"250.00\", \"401.9\", \"V58.11\"],\n              \"procedure_codes\": [\"12345\", \"00000\", \"INVALID\"],\n              \"loinc_codes\": [\"0000-0\", \"INVALID-LOINC\"],\n              \"snomed_codes\": [\"12345\", \"INVALID-SNOMED\"],\n              \"modifier_codes\": [\"XX\", \"ZZ\"],\n              \"service_date\": \"2024-12-01\",\n              \"coding_version\": \"ICD-9-CM-2015\"\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"CSV\"\n        emirate \"Abu Dhabi\"\n      }\n    }\n  }\n}\n\ntest medical_codes_uae_local_codes {\n  functions [ValidateMedicalCodes]\n  args {\n    data_sample {\n      resource_type \"Claims\"\n      raw_data #\"\n        {\n          \"claims\": [\n            {\n              \"claim_id\": \"CLM-UAE-001\",\n              \"patient_id\": \"UAE-PAT-456\",\n              \"provider_id\": \"DHA-PROV-789\",\n              \"diagnosis_codes\": [\"E11.9\"],\n              \"procedure_codes\": [\"99213\"],\n              \"dha_local_codes\": [\"DHA-PROC-2024-001\", \"DHA-DIAG-2024-002\"],\n              \"doh_local_codes\": [\"DOH-LAB-2024-001\"],\n              \"emirates_pharmacy_codes\": [\"UAE-MED-2024-123\"],\n              \"local_facility_codes\": [\"DXB-FAC-001\"],\n              \"service_date\": \"2024-12-01\",\n              \"emirate\": \"Dubai\",\n              \"cross_emirates_codes\": {\n                \"origin\": \"Dubai\",\n                \"destination\": \"Abu Dhabi\",\n                \"referral_code\": \"CROSS-REF-2024-001\"\n              }\n            }\n          ]\n        }\n      \"#\n      context {\n        source_system \"eClaimLink\"\n        emirate \"Dubai\"\n      }\n    }\n  }\n}\n",
}


